package com.zoutiw.bibla.data

object FirstPeterData {
    val verses: List<Verse> = listOf(
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 1, text = "Se mwen menm, Pyè, apòt Jezikri, k'ap ekri lèt sa a pou nou tout ki fè pati pèp Bondye te chwazi a men k'ap viv tankou etranje, gaye nan peyi Pon, Galasi, Kapadòs, Lazi ak Bitini.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 2, text = "Se Bondye Papa a ki te chwazi nou dapre plan li te fè davans lan. Gremesi Sentespri li a, li mete nou apa pou li pou n' obeyi Jezikri, pou san Jezikri ki koule pou nou an ka mete nou nan kondisyon pou sèvi Bondye. M'ap mande Bondye pou nou resevwa anpil benediksyon ak kè poze.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 3, text = "Ann fè lwanj Bondye, Papa Jezikri, Seyè nou an. Paske, nan kè sansib li, li ban nou lavi ankò lè li te fè Jezikri leve soti vivan nan lanmò a. Sa fè nou viv ak anpil espwa.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 4, text = "N'ap tann lè pou n' resevwa eritaj Bondye a, eritaj ki p'ap janm pouri, ki p'ap janm sal, ni ki p'ap janm pèdi frechè l', eritaj li sere pou nou nan syèl la.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 5, text = "Paske nou menm nou gen konfyans nan li, Bondye ap pwoteje nou ak pouvwa li jouk la delivre nou jan sa pral parèt aklè nan dènye tan an.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 6, text = "Sa fè nou kontan anpil, menm si koulye a nou blije gen lapenn anpil pou yon ti tan, avèk tout kalite eprèv n'ap sibi yo.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 7, text = "Paske, konfyans nou se tankou lò li ye. Yo blije pase lò a, ki yon bagay perisab, nan dife pou wè si l' bon. Konsa tou, konfyans nou ki gen plis valè pase lò a gen pou pase anba eprèv tou, pou nou ka resevwa lwanj, onè ak respè lè Jezikri va parèt.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 8, text = "Nou renmen l', atout nou pa te wè l'; nou gen konfyans nan li, atout nou pa wè l' koulye a. Konsa, nou kontan ak yon kontantman nou pa ka esplike men ki merite lwanj,", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 9, text = "paske nou jwenn sa nou t'ap chache lè nou te kwè a: delivrans pou nanm nou.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 10, text = "Pwofèt yo te chache anpil, yo te fouye anpil pou yo te ka konnen ki jan Bondye t'ap delivre nou. Yo te di davans ki kalite favè Bondye tapral fè nou.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 11, text = "Lespri Kris la ki te nan yo te fè yo konnen davans tou sa Kris la tapral soufri, ansanm ak lwanj ki t'ap tann li apre sa. Men, yo t'ap chache konnen tou kilè ak nan ki sikonstans sa tapral rive.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 12, text = "Se konsa, Bondye fè yo konnen sèvis yo t'ap fè lè yo te bay mesaj la, se pa t' pou yo, men pou nou. Gremesi moun k'ap anonse nou bon nouvèl la, avèk pouvwa Sentespri ki soti nan syèl la, nou konnen bagay sa yo koulye a, bagay ata zanj yo ta renmen konprann.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 13, text = "Se poutèt sa, konnen byen sa nou pral fè. Mete tèt nou an plas. Mete tout espwa nou nan benediksyon nou pral resevwa lè Jezikri va parèt.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 14, text = "Tankou timoun obeyisan, pa kite move lanvi nou te genyen nan tan lontan yo mennen lavi nou ankò, tankou anvan lè nou pa t' konn Bondye.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 15, text = "Okontrè, nan tou sa n'ap fè, se pou nou bon nèt, tankou Bondye ki rele nou an bon nèt tou.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 16, text = "Paske, men sa ki ekri nan Liv la: Se pou nou bon nèt, paske mwen menm, mwen bon nèt.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 17, text = "Si lè n'ap lapriyè nou rele Bondye: Papa, li menm ki p'ap gade sou figi moun men k'ap jije tout moun menm jan dapre sa yo fè, se pou nou viv ak krentif pou Bondye pandan ti tan ki rete pou nou pase sou tè a.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 18, text = "Bondye wete nou nan lavi san sans nou te resevwa nan men zansèt nou yo. Nou konnen sa li te peye pou sa. Se pa t' avèk bagay ki ka pèdi valè yo tankou lajan ak lò.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 19, text = "Men, se avèk gwo ofrann san Kris la ki te koule lè li te ofri tèt li tankou yon ti mouton san defo ni ankenn enfimite.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 20, text = "Bondye te chwazi l' pou sa depi anvan li te kreye tout bagay. Men, se nan dènye tan sa yo li vin parèt pou byen nou.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 21, text = "Gremesi Kris la, nou gen konfyans nan Bondye ki te fè l' leve soti vivan nan lanmò, nan Bondye ki te ba l' lwanj. Konsa, nou mete tout konfyans nou ak tout espwa nou nan Bondye.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 22, text = "Koulye a, lè n'ap obeyi verite a, nou nan kondisyon pou nou fè sèvis Bondye, pou nou sa gen yon renmen sensè pou frè yo. Se sak fè, se pou nou yonn renmen lòt ak tout kè nou, ak tout fòs nou.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 23, text = "Gremesi pawòl Bondye a ki yon pawòl vivan epi ki la pou tout tan, nou resevwa yon lòt lavi. Fwa sa a, nou pa soti nan yon jèm ki ka mouri, men nan yon jèm ki pa ka mouri.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 24, text = "Jan sa ekri nan Liv la: Moun, se tankou zèb yo ye. Tout bèl ou wè yo bèl la, se tankou flè zèb la yo ye. Zèb la chèch, flè a tonbe.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 1, verseNumber = 25, text = "Men, pawòl Bondye a la pou tout tan. Se pawòl sa a bon nouvèl la te pote ban nou. 1 Piè", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 1, text = "Se poutèt sa, derasinen tout mechanste ki te nan lavi nou. Sispann bay manti, sispann fè ipokrizi, sispann fè jalouzi ak tripotaj.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 2, text = "Tankou timoun ki fenk fèt, se pou nou kriye dèyè bon lèt san dekoupe ki soti nan Bondye, pou nou kapab grandi, pou nou kapab fin delivre nèt.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 3, text = "Paske, nou deja goute Mèt la, nou wè jan li bon.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 4, text = "Pwoche vin jwenn Seyè a, li menm ki wòch vivan an. Moun te voye li jete paske pou yo li te san valè. Men, li gen anpil valè pou Bondye ki te chwazi li.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 5, text = "Nou menm tou, tankou wòch vivan, kite Bondye sèvi ak nou pou bati kay li a ak pouvwa Sentespri, pou nou ka sèvi l' tankou prèt k'ap viv pou li. Konsa, gremesi Jezikri, n'a ofri bay Bondye ofrann ki soti nan kè nou, ofrann ki pou fè l' plezi.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 6, text = "Se poutèt sa nou jwenn sa ekri nan Liv la: Men li, mwen mete yon wòch nan mitan peyi Siyon, yon wòch kwen mwen menm mwen chwazi epi ki gen anpil valè. Moun ki mete konfyans yo nan li p'ap janm soti wont.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 7, text = "Pou nou menm ki mete konfyans nou nan wòch la, wòch la gen anpil valè. Men, pou moun ki pa mete konfyans yo nan li, sa ki ekri nan Liv la pral rive vre: Wòch moun ki t'ap bati yo te voye jete a, se li menm ki tounen wòch ki kenbe kay la.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 8, text = "Se yon wòch k'ap fè moun bite, yon gwo wòch k'ap fè yo tonbe. Yo bite, paske yo pa koute pawòl la. Enben, se sa ki te sere pou yo.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 9, text = "Men nou menm, nou se yon ras Bondye chwazi, yon bann prèt k'ap sèvi Wa a, yon nasyon k'ap viv apa pou Bondye, yon pèp li achte. Li fè tou sa pou n' te ka fè tout moun konnen bèl bagay Bondye te fè yo, Bondye ki rele nou soti nan fènwa a pou nou antre nan bèl limyè li a.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 10, text = "Anvan sa, nou pa t' menm yon nasyon. Men koulye a, nou se pèp Bondye a. Anvan sa, Bondye pa t' gen pitye pou nou. Koulye a, li gen pitye pou nou.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 11, text = "Zanmi m' yo, men sa m'ap mande nou. M'ap pale ak nou koulye a tankou ak moun ki etranje, ki depasaj sou latè: Se pou nou kenbe tèt ak tout egzijans lachè a k'ap goumen kont nanm nou.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 12, text = "Se pou nou gen yon bon kondit nan mitan moun sa yo ki pa konn Bondye. Konsa, lè y'ap pale nou mal, lè y'ap di se yon bann malfektè nou ye, y'a gen pou yo rekonèt tout byen n'ap fè a, y'a fè lwanj Bondye lè la vin jije yo.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 13, text = "Soumèt devan tout otorite lèzòm etabli. Fè sa pou Bondye. Soumèt devan wa a, paske se li ki pi gwo chèf.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 14, text = "Soumèt devan majistra yo, paske wa a voye yo pou peni tout moun k'ap fè mal, pou fè lwanj tout moun k'ap fè byen.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 15, text = "Paske, Bondye vle pou n' fè sa ki byen, pou n' ka fèmen bouch moun sa yo ki pa konn anyen, ki san konprann.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 16, text = "Se pou nou viv tankou moun ki gen tout libète yo. Men, nou pa dwe pran libète sa a sèvi yon kouvèti pou nou fè sa ki mal. Se pou nou viv tankou moun k'ap sèvi Bondye.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 17, text = "Se pou nou bay chak moun respè li merite. renmen tout frè nou yo, gen krentif pou Bondye, respekte wa a.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 18, text = "Nou menm domestik yo, nou fèt pou soumèt devan mèt nou yo avèk tout respè yo merite. Pa sèlman devan mèt ki bon yo, mèt ki gen bon kè yo, men devan mèt ki gen karaktè difisil yo tou.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 19, text = "Bondye va beni nou, si, lè y'ap fè nou soufri pou sa nou pa fè, nou sipòte lafliksyon an paske nou konnen se sa Bondye vle.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 20, text = "Ki lwanj ki gen nan sa si nou sipòte lè y'ap maltrete nou pou sa nou fè ki mal? Men, si lè nou fè byen, nou sipòte tou sa y'ap fè nou soufri poutèt byen nou fè a, sa se yon bèl bagay devan Bondye.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 21, text = "Se pou sa menm Bondye te rele nou, paske Kris la te soufri pou nou. Li kite yon egzanp pou nou swiv pye pou pye.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 22, text = "Li pa t' janm fè ankenn peche. Ankenn manti pa t' janm soti nan bouch li.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 23, text = "Lè yo t'ap joure l', li pa t' reponn. Lè yo t'ap maltrete l', li pa t' mennase pesonn. Men, li renmèt kòz li nan men Bondye k'ap jije tout bagay san patipri.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 24, text = "Kris la te pote peche nou yo nan kò li sou bwa a, pou nou te kapab mouri annegad peche, pou nou te ka viv dwat devan Bondye. Li te kite yo maltrete l' pou l' te ka geri nou.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 2, verseNumber = 25, text = "Nou te tankou mouton ki te pèdi bann yo. Men, koulye a, nou tounen vin jwenn Kris la ki gadò nou, k'ap veye sou nanm nou. 1 Piè", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 1, text = "Menm jan an tou, nou menm medam, soumèt devan mari nou. Konsa, si gen nan mari nou yo ki pa kwè nan Bondye, kondit nou kont pou fè yo kwè, san n' pa janm bezwen louvri bouch nou,", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 2, text = "paske y'a wè jan nou viv byen, jan nou respekte yo.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 3, text = "Nou pa bezwen fè kò nou bèl ak bagay moun ka wè, tankou lè n'ap fè anpil kwafi estraòdenè, lè n'ap mete kantite bijou an lò ak kantite rad ki koute chè sou nou.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 4, text = "Okontrè, se sa ki nan kè nou ki tout bèlte nou, yon bèlte ki p'ap janm pase. Se pou nou gen yon karaktè dou, yon karaktè poze. Se sa ki gen valè devan Bondye.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 5, text = "Nan tan lontan, se konsa medam ki t'ap viv pou Bondye yo te fè tèt yo bèl: yo te mete espwa yo nan Bondye, yo te soumèt devan mari yo.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 6, text = "Se konsa Sara te ye. Li te soumèt devan Abraram jouk pou li te rele l' mèt. Nou menm tou, medam, nou se pitit Sara, si nou fè sa ki byen san nou pa pè anyen.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 7, text = "Menm jan an tou, nou menm mari, nan tout bagay se pou nou viv byen ak madanm nou paske yo pi fèb pase nou. Ba yo tout respè yo merite, paske yo menm tou y'a resevwa menm lavi avèk nou tankou yon favè nan men Bondye. Konsa, anyen p'ap antrave lapriyè nou.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 8, text = "Pou fini, nou tout nou dwe dakò yonn ak lòt, se pou nou gen menm santiman yonn pou lòt. Se pou nou yonn renmen lòt tankou frè ak sè, se pou nou gen bon kè, san lògèy.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 9, text = "Pa rann moun mal pou mal, jouman pou jouman. Okontrè, lè konsa, mande benediksyon pou yo, paske se benediksyon Bondye te pwomèt pou l' ban nou lè li te rele nou an.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 10, text = "Paske: Si yon moun vle jwi lavi a, si l' anvi pase kèk bon kadè sou latè, se pou l' kenbe lang li pou l' pa pale moun mal. Se pou l' veye bouch li pou l' pa bay manti.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 11, text = "Se pou l' sispann fè sa ki mal, se pou l' fè sa ki byen. Se pou l' chache viv byen ak moun. Se pou l' fè sa li kapab pou li viv byen ak tout moun.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 12, text = "Paske, Bondye veye sou moun k'ap mache dwat devan li. Li tande yo lè y'ap lapriyè nan pye l'. Men, l'ap vire do bay moun k'ap fè sa ki mal.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 13, text = "Ki moun ki ka fè nou mal si se byen ase nou vle fè?", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 14, text = "Men, si nou rive soufri poutèt byen nou fè, konsidere sa tankou yon benediksyon. Nou pa bezwen pè moun, nou pa bezwen toumante tèt nou pou anyen.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 15, text = "Sèl bagay, se pou nou rekònèt se Kris la ki Seyè a nan kè nou. Se pou n' toujou pare pou n' defann tèt nou chak fwa yon moun mande nou esplikasyon sou espwa nou gen nan kè nou an.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 16, text = "Men, fè sa avèk dousè ak tout respè. Kenbe konsyans nou pwòp. Konsa, moun k'ap pale nou mal poutèt bon kondit nou gen nan Kris la, se yo menm ki va wont pou pawòl yo te di lè yo t'ap joure nou an.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 17, text = "Se volonte Bondye pou nou fè sa ki byen. Menm si nou gen pou n' soufri, li pa vle nou fè sa ki mal.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 18, text = "Paske, Kris la menm mouri yon sèl fwa pou peche nou yo, li p'ap janm mouri ankò. Li menm ki t'ap mache dwat devan Bondye, li mouri pou moun ki pa t'ap mache dwat yo, pou l' te ka mennen nou bay Bondye. Li te mouri nan kò l', men ak pouvwa Lespri Bondye a, li leve vivan ankò.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 19, text = "Ak pouvwa menm Lespri a, li te al preche nanm ki nan prizon yo.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 20, text = "Se nanm moun ki nan tan lontan te derefize kwè nan Bondye. Se te sou tan Noe. Lè sa a, Bondye t'ap tann ak pasyans pandan Noe t'ap fè gwo batiman an. Nan batiman sa a, se kèk moun sèlman, wit moun antou, ki te sove nan dlo a.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 21, text = "Pou nou menm, dlo sa a kanpe pou dlo batèm lan k'ap delivre nou koulye a. Batèm lan, se pa yon bagay k'ap wete kras sou kò nou. Men, se yon angajman nou pran devan Bondye ak yon konsyans san repwòch. Bondye sove nou gremesi Jezikri ki te leve soti vivan nan lanmò,", bookId = 60),
        Verse(book = "1 Pyè", chapter = 3, verseNumber = 22, text = "ki moute nan syèl la, ki chita sou bò dwat Bondye kote l'ap domennen sou tout zanj yo, sou tout chèf yo ak sou tout otorite yo. 1 Piè", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 1, text = "Se poutèt sa, menm jan Kris la te soufri nan kò li, nou menm tou se pou nou pare pou n' soufri menm jan an tou. Paske, lè yon moun soufri nan kò li, li pa gen anyen pou l' wè ak peche ankò.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 2, text = "Se pou li viv ti rès tan li gen pou l' viv sou tè a dapre egzijans volonte Bondye, pa dapre egzijans lachè.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 3, text = "Paske, nan tan lontan, nou te gen kont tan nou pou n' te fè tou sa moun ki pa konnen Bondye yo ap fè. Lè sa a, nou t'ap viv nan libètinaj, nan lanvi, nan bwè tafya, nan debòch, nan banbòch, nan sèvi zidòl, bagay lalwa defann nou fè.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 4, text = "Koulye a, moun sa yo twouve sa dwòl dèske nou pa fè bann ak yo ankò nan tout eksè sa yo. Se poutèt sa, y'ap pale nou mal.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 5, text = "Men, yo gen pou yo rann kont bay Bondye ki deja pare pou jije ni moun ki vivan yo ni moun ki mouri yo.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 6, text = "Se pou sa menm yo te anonse bon nouvèl la bay moun ki mouri yo. Konsa, si lè yo te sou latè yo te tonbe anba jijman Bondye tankou tout moun, koulye a yo ka viv nan pouvwa Lespri Bondye a, jan Bondye vle l' la.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 7, text = "Tout bagay prèt pou fini. Se pou nou kenbe tèt nou anplas, veye kò nou pou n' ka lapriyè.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 8, text = "Anvan tout bagay, se pou nou yonn renmen lòt anpil. Paske, lè nou renmen, sa fè Bondye padonnen anpil peche.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 9, text = "Se pou nou yonn resevwa lòt lakay nou san plenyen.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 10, text = "Chak moun dwe pran kado Bondye ba yo a pou yo rann lòt yo sèvis. Konsa, tankou bon jeran, n'a pran kado Bondye yo, ki divès kalite, n'a fè yo travay.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 11, text = "Si yon moun ap pale, se pou l' pale tankou si se te pawòl Bondye li t'ap di. Si yon moun ap rann sèvis, se pou li fè l' ak fòs Bondye ba li. Konsa, nan tout bagay lwanj lan va pou Bondye, gremesi Jezikri. Se pou Jezikri tout lwanj ak tout pouvwa pou tout tan. Amèn.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 12, text = "Frè m' yo, nou pa bezwen sezi devan gwo eprèv sa yo k'ap tonbe sou nou tankou yon gwo dife. Nou pa bezwen konprann sa se yon bagay estwòdenè k'ap rive nou la a.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 13, text = "Okontrè, fè kè n' kontan. Paske, menm jan nou patisipe nan soufrans Kris yo, konsa tou n'a kontan nèt ale lè gwo pouvwa Kris la va parèt.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 14, text = "Si yo joure nou paske n'ap swiv Kris la, konsidere sa tankou yon benediksyon. Paske, Lespri ki gen gwo pouvwa a, Lespri Bondye a nan nou.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 15, text = "Mwen swete pou pesonn nan nou pa gen pou li soufri paske li te touye moun, osinon paske li te fè sa ki mal, osinon paske li te foure bouch li nan zafè ki pa gade li.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 16, text = "Men, si yon moun ap soufri paske se kretyen li ye, li pa bezwen wont pou sa. Okontrè, se pou li fè lwanj Bondye dèske li pote non Kris la.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 17, text = "Paske, dat la rive pou jijman Bondye a konmanse. L'ap konmanse ak moun ki nan kay Bondye a anvan. Si li konmanse ak nou, nou pa bezwen mande sak pral rive moun sa yo ki pa koute bon nouvèl Bondye a.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 18, text = "Tankou sa ekri nan Liv la: Si moun k'ap viv dwat devan Bondye yo pa fasil pou sove, nou pa bezwen mande sa k'ap rive moun ki pa kwè nan Bondye yo, moun k'ap viv nan peche yo.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 4, verseNumber = 19, text = "Se poutèt sa, moun k'ap soufri paske se sa Bondye vle pou yo a, se pou yo pa sispann fè sa ki byen, se pou yo renmèt nanm yo nan men Bondye ki kreye yo, epi ki p'ap lage yo. 1 Piè", bookId = 60),
        Verse(book = "1 Pyè", chapter = 5, verseNumber = 1, text = "Mwen menm ki yon chèf reskonsab, m'ap pale koulye a ak chèf reskonsab ki nan mitan nou yo. Mwen menm ki te wè jan Kris la te soufri a, mwen pral patisipe tou nan bèl pouvwa Bondye ki gen pou parèt la.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 5, verseNumber = 2, text = "Men sa m'ap di nou: Tankou gadò, se pou nou swen bann mouton Bondye ki sou kont nou an. Pa fè sa tankou si se fòse y'ap fòse nou. Men, fè l' paske nou vle fè sa Bondye vle. Pa fè travay la tankou si se dèyè lajan nou ye. Men, fè l' ak tout kè nou.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 5, verseNumber = 3, text = "Pa fè menm jan ak chèf k'ap maltrete moun ki sou kont yo. Okontrè, se pou nou tounen yon egzanp pou mouton yo.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 5, verseNumber = 4, text = "Konsa, lè gran gadò a va parèt, n'a resevwa yon kouwòn ki p'ap janm fennen: n'a resevwa lwanj Bondye.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 5, verseNumber = 5, text = "Menm jan an tou, nou menm jennjan yo, se pou nou soumèt devan chèf reskonsab yo. Nan tout rapò nou yonn ak lòt, se pou nou soumèt devan Bondye. Paske Bondye pran pozisyon kont moun ki gen lògèy. Men, moun ki soumèt devan l', li ba yo favè li.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 5, verseNumber = 6, text = "Se poutèt sa, soumèt nou devan Bondye ki gen pouvwa, konsa la leve nou lè pou l' leve nou an.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 5, verseNumber = 7, text = "Lage tout tèt chaje nou yo ba li, paske l'ap pran swen nou.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 5, verseNumber = 8, text = "Kenbe tèt nou anplas, rete sou prigad nou. Paske dyab la, lènmi nou an, ap veye nou tankou yon lyon ki move, k'ap chache moun pou l' devore.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 5, verseNumber = 9, text = "Kanpe fèm nan konfyans nou, kenbe tèt avè l', paske nou konnen lòt frè nou yo ki nan lemonn ap soufri menm soufrans ak nou.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 5, verseNumber = 10, text = "Men, apre n'a fin soufri yon ti tan, Bondye li menm va rann nou bon nèt, la kenbe nou fèm, la ban nou fòs, l'ap fè nou kanpe san brannen. Paske Bondye bay tout kalite favè. Se li menm ki te rele nou, gremesi Kris la, pou n' te patisipe nan pouvwa li ki p'ap janm fini.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 5, verseNumber = 11, text = "Se pou li tout pouvwa a, depi tout tan ak pou tout tan. Amèn.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 5, verseNumber = 12, text = "Se avèk konkou frè Silven, yon nonm serye dapre sa mwen konnen, m'ap ekri nou lèt sa a, pou m' ka ankouraje nou, pou m' fè nou konnen jan favè Bondye pou nou an se yon bagay ki vre. Kenbe fèm nan li.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 5, verseNumber = 13, text = "Legliz Bondye chwazi nan lavil Babilòn lan voye bonjou pou nou, ansanm ak Mak, pitit mwen an.", bookId = 60),
        Verse(book = "1 Pyè", chapter = 5, verseNumber = 14, text = "Bò pa nou, yonn di lòt bonjou pou mwen, yonn bo lòt tankou frè ak frè. Mwen mande pou nou tout k'ap viv ansanm nan Kris la, pou nou gen kè poze. 1 Piè", bookId = 60)
    )
